INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-resource-001', 'bio', 'ความหลากหลายทางชีวภาพและสิ่งแวดล้อม', 'ทรัพยากรธรรมชาติ', '[]', 'easy', 'คำนวณอัตราการลดลงสุทธิของทรัพยากรธรรมชาติ (ระดับค่าย สอวน)', NULL, 'mc5', 'ป่าไม้แห่งหนึ่งมีต้นไม้ถูกตัดไปปีละ 500 ต้น และปลูกทดแทนปีละ 300 ต้น อัตราการลดลงสุทธิของจำนวนต้นไม้ต่อปีเท่ากับกี่ต้น', '["100 ต้น", "150 ต้น", "200 ต้น", "300 ต้น", "500 ต้น"]', '200 ต้น', '["อัตราการลดลงสุทธิ = จำนวนที่ตัด - จำนวนที่ปลูกทดแทน = 500-300 = 200 ต้นต่อปี"]', '["ตอบจำนวนที่ตัดทั้งหมดโดยลืมหักส่วนที่ปลูกทดแทน"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-biodiversity-001', 'bio', 'ความหลากหลายทางชีวภาพและสิ่งแวดล้อม', 'ความหลากหลายของสิ่งมีชีวิต', '[]', 'hard', 'คำนวณดัชนีความหลากหลายทางชีวภาพของซิมป์สัน (ระดับค่าย สอวน)', NULL, 'mc5', 'ชุมชนสิ่งมีชีวิตหนึ่งมี 4 สปีชีส์ มีจำนวนตัว 40, 30, 20, 10 ตัวตามลำดับ (รวม 100 ตัว) ดัชนีความหลากหลายของซิมป์สัน (1-D) เท่ากับเท่าใด', '["0.30", "0.50", "0.60", "0.70", "0.90"]', '0.70', '["หาสัดส่วนแต่ละสปีชีส์: 0.4, 0.3, 0.2, 0.1", "D = Σ(pi²) = 0.16+0.09+0.04+0.01 = 0.30", "ดัชนีความหลากหลาย = 1-D = 1-0.30 = 0.70"]', '["ลืมยกกำลังสองสัดส่วนก่อนรวม หรือลืมนำ 1 ไปลบผลรวม"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-biochem-001', 'bio', 'หน่วยพื้นฐานของสิ่งมีชีวิต', 'เคมีพื้นฐานของสิ่งมีชีวิต', '[]', 'medium', 'นับจำนวนพันธะเพปไทด์จากจำนวนกรดอะมิโน (ระดับค่าย สอวน)', NULL, 'mc5', 'โปรตีนสายหนึ่งประกอบด้วยกรดอะมิโน 50 โมเลกุลเรียงต่อกัน เกิดพันธะเพปไทด์ทั้งหมดกี่พันธะ', '["48", "49", "50", "51", "100"]', '49', '["กรดอะมิโน n ตัวเรียงต่อกันเป็นสายตรงจะเกิดพันธะเพปไทด์ = n-1 พันธะ", "50-1 = 49 พันธะ"]', '["ตอบจำนวนกรดอะมิโนโดยตรง (50) แทนที่จะลบ 1"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-digestion-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'ระบบย่อยอาหาร', '[]', 'hard', 'คำนวณมวลผลิตภัณฑ์จากการย่อยแป้งด้วยปฏิกิริยาไฮโดรลิซิส (ระดับค่าย สอวน)', NULL, 'mc5', 'แป้ง (starch) มวล 18 กรัม ถูกย่อยสมบูรณ์เป็นกลูโคสอิสระด้วยปฏิกิริยาไฮโดรลิซิส โดยหน่วยกลูโคสในแป้งมีมวลโมเลกุลเฉลี่ย 162 กรัมต่อโมล และกลูโคสอิสระมีมวลโมเลกุล 180 กรัมต่อโมล จะได้กลูโคสกี่กรัม', '["16.2 กรัม", "18 กรัม", "20 กรัม", "22 กรัม", "25 กรัม"]', '20 กรัม', '["โมลหน่วยกลูโคสในแป้ง = 18/162 = 0.111 โมล", "ไฮโดรลิซิสเติมน้ำเปลี่ยนเป็นกลูโคสอิสระ (มวลโมล 180): มวลกลูโคส = 0.111×180 = 20 กรัม"]', '["ลืมว่าไฮโดรลิซิสเติมมวลของน้ำเข้าไป ตอบมวลเท่าเดิม (18 กรัม)"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-immunity-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'ระบบน้ำเหลืองและภูมิคุ้มกัน', '[]', 'hard', 'แปลผลค่าไทเตอร์แอนติบอดีจากการเจือจางลำดับ (ระดับค่าย สอวน)', NULL, 'mc5', 'การตรวจไทเตอร์ (titer) ของแอนติบอดีด้วยวิธีเจือจางลำดับแบบเท่าตัว (two-fold serial dilution) พบว่าหลอดสุดท้ายที่ยังตรวจพบปฏิกิริยาคือหลอดที่ 5 (นับหลอดแรกเป็นเจือจาง 1:2) ค่าไทเตอร์ของแอนติบอดีนี้เท่ากับเท่าใด', '["1:8", "1:16", "1:32", "1:64", "1:128"]', '1:32', '["การเจือจางเท่าตัวหลอดที่ n มีความเข้มข้น 1:2ⁿ", "หลอดที่ 5: 1:2⁵ = 1:32"]', '["นับจำนวนหลอดผิดโดยเริ่มจาก 0 แทนที่จะเริ่มจากหลอดที่ 1 คือ 1:2"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-nervous-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'ระบบประสาทและการเคลื่อนที่', '[]', 'medium', 'คำนวณเวลาการนำกระแสประสาทจากอัตราเร็วและระยะทาง (ระดับค่าย สอวน)', NULL, 'mc5', 'เส้นประสาทเส้นหนึ่งมีอัตราเร็วการนำกระแสประสาท 100 เมตรต่อวินาที ถ้าระยะทางจากไขสันหลังไปยังปลายเท้าเท่ากับ 1 เมตร กระแสประสาทใช้เวลาเดินทางกี่มิลลิวินาที', '["1", "5", "10", "50", "100"]', '10', '["เวลา = ระยะทาง/อัตราเร็ว = 1/100 = 0.01 วินาที = 10 มิลลิวินาที"]', '["ลืมแปลงหน่วยจากวินาทีเป็นมิลลิวินาที"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-reproduction-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'ระบบสืบพันธุ์', '[]', 'easy', 'ประยุกต์ใช้ความรู้เรื่องรอบเดือนและช่วงตกไข่ (ระดับค่าย สอวน)', NULL, 'mc5', 'ผู้หญิงคนหนึ่งมีรอบเดือนสม่ำเสมอทุก 28 วัน และตกไข่ในวันที่ 14 นับจากวันแรกที่มีประจำเดือน ถ้ามีประจำเดือนครั้งล่าสุดเริ่มวันที่ 1 มกราคม วันที่คาดว่าจะตกไข่คือวันใด', '["7 มกราคม", "10 มกราคม", "14 มกราคม", "21 มกราคม", "28 มกราคม"]', '14 มกราคม', '["นับวันแรกของประจำเดือนเป็นวันที่ 1 ของรอบ (1 มกราคม)", "วันตกไข่คือวันที่ 14 ของรอบ = 14 มกราคม"]', '["นับวันเริ่มต้นผิดพลาด เช่น เริ่มนับจาก 0 แทนที่จะนับจาก 1"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-endocrine-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'ระบบต่อมไร้ท่อ', '[]', 'hard', 'คำนวณปริมาณฮอร์โมนคงเหลือจากครึ่งชีวิตในกระแสเลือด (ระดับค่าย สอวน)', NULL, 'mc5', 'ฮอร์โมนชนิดหนึ่งมีครึ่งชีวิตในกระแสเลือด 20 นาที ถ้าฉีดฮอร์โมนเข้าเส้นเลือดปริมาณเริ่มต้น 8 มิลลิกรัม หลังจากผ่านไป 60 นาที จะเหลือฮอร์โมนในเลือดกี่มิลลิกรัม', '["0.5", "1", "2", "4", "6"]', '1', '["60 นาที = 3 ครึ่งชีวิต (60/20=3)", "ปริมาณคงเหลือ = 8×(1/2)³ = 8/8 = 1 มิลลิกรัม"]', '["หารมวลตั้งต้นด้วยเวลาโดยตรงแทนที่จะยกกำลังตามจำนวนครึ่งชีวิต"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-behavior-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'พฤติกรรมของสัตว์', '[]', 'easy', 'คำนวณงบเวลา (time budget) ของพฤติกรรมสัตว์ (ระดับค่าย สอวน)', NULL, 'mc5', 'นกชนิดหนึ่งใช้เวลาหาอาหาร 80% ของเวลาทั้งหมดใน 1 วัน (24 ชั่วโมง) นกนี้ใช้เวลาหาอาหารกี่ชั่วโมงต่อวัน', '["16.0", "17.6", "18.5", "19.2", "20.0"]', '19.2', '["เวลาหาอาหาร = 0.8×24 = 19.2 ชั่วโมง"]', '["คำนวณเปอร์เซ็นต์ผิดโดยหารแทนที่จะคูณ"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-planttissue-001', 'bio', 'โครงสร้างและการทำงานของส่วนต่างๆ ในพืช', 'เนื้อเยื่อพืช', '[]', 'medium', 'คำนวณการเจริญเติบโตทุติยภูมิของลำต้นจากเนื้อเยื่อเจริญด้านข้าง (ระดับค่าย สอวน)', NULL, 'mc5', 'ต้นไม้ต้นหนึ่งมีเส้นผ่านศูนย์กลางลำต้นเพิ่มขึ้นปีละ 2 เซนติเมตร จากการแบ่งเซลล์ของเนื้อเยื่อเจริญด้านข้าง (vascular cambium) ถ้าเริ่มต้นมีเส้นผ่านศูนย์กลาง 10 เซนติเมตร หลังจาก 5 ปี เส้นผ่านศูนย์กลางจะเท่ากับเท่าใด', '["12 ซม.", "15 ซม.", "18 ซม.", "20 ซม.", "25 ซม."]', '20 ซม.', '["เส้นผ่านศูนย์กลางสุดท้าย = เริ่มต้น + อัตราเพิ่ม×จำนวนปี = 10+2×5 = 20 เซนติเมตร"]', '["ลืมบวกเส้นผ่านศูนย์กลางเริ่มต้น ตอบแค่ส่วนที่เพิ่มขึ้น"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-flowerrepro-001', 'bio', 'โครงสร้างและการทำงานของส่วนต่างๆ ในพืช', 'การสืบพันธุ์ของพืชดอก', '[]', 'easy', 'คำนวณจำนวนเมล็ดจากผลของการปฏิสนธิซ้อน (ระดับค่าย สอวน)', NULL, 'mc5', 'ในกระบวนการปฏิสนธิของพืชดอก 20 ดอก แต่ละดอกมีออวุลพัฒนาเป็นเมล็ดสำเร็จเฉลี่ย 5 เมล็ดต่อดอก จะได้เมล็ดทั้งหมดกี่เมล็ด', '["25", "50", "80", "100", "120"]', '100', '["จำนวนเมล็ดทั้งหมด = จำนวนดอก × เมล็ดเฉลี่ยต่อดอก = 20×5 = 100 เมล็ด"]', '["บวกแทนคูณ (20+5=25)"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-plantgrowth-001', 'bio', 'โครงสร้างและการทำงานของส่วนต่างๆ ในพืช', 'การเจริญเติบโตของพืช', '[]', 'easy', 'คำนวณอัตราการเจริญเติบโตเฉลี่ยของพืช (ระดับค่าย สอวน)', NULL, 'mc5', 'ต้นกล้าต้นหนึ่งสูง 5 เซนติเมตรในวันที่ 0 และสูง 20 เซนติเมตรในวันที่ 10 ถ้าเจริญเติบโตแบบอัตราคงที่ อัตราการเจริญเติบโตเฉลี่ยเท่ากับกี่เซนติเมตรต่อวัน', '["0.5", "1.0", "1.5", "2.0", "2.5"]', '1.5', '["อัตราการเจริญเติบโต = (ความสูงสุดท้าย-ความสูงเริ่มต้น)/เวลา = (20-5)/10 = 1.5 ซม./วัน"]', '["ลืมหักความสูงเริ่มต้นออกก่อนหารด้วยเวลา"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-mutation-001', 'bio', 'พันธุศาสตร์และวิวัฒนาการ', 'มิวเทชัน', '[]', 'hard', 'คำนวณจำนวนมิวเทชันที่คาดว่าจะเกิดจากอัตรากลายพันธุ์ (ระดับค่าย สอวน)', NULL, 'mc5', 'ยีนหนึ่งมีความยาว 1,500 คู่เบส มีอัตราการกลายพันธุ์เท่ากับ 2×10⁻⁶ ต่อคู่เบสต่อรุ่น จำนวนมิวเทชันที่คาดว่าจะเกิดขึ้นในยีนนี้ต่อรุ่นเท่ากับเท่าใด', '["0.0003", "0.003", "0.03", "0.3", "3"]', '0.003', '["จำนวนมิวเทชันที่คาดหวัง = ความยาวยีน × อัตรากลายพันธุ์ = 1500×2×10⁻⁶ = 0.003"]', '["คำนวณเลขยกกำลังฐาน 10 ผิดพลาด ทำให้ตำแหน่งทศนิยมคลาดเคลื่อน"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-dnatech-001', 'bio', 'พันธุศาสตร์และวิวัฒนาการ', 'เทคโนโลยีดีเอ็นเอ', '[]', 'medium', 'คำนวณจำนวนดีเอ็นเอที่เพิ่มขึ้นจากปฏิกิริยา PCR (ระดับค่าย สอวน)', NULL, 'mc5', 'ปฏิกิริยา PCR เพิ่มจำนวนดีเอ็นเอเป็น 2 เท่าทุกรอบ ถ้าเริ่มต้นมีดีเอ็นเอต้นแบบ 1 โมเลกุล ผ่านไป 10 รอบ (cycles) จะมีดีเอ็นเอกี่โมเลกุล (ไม่คิดประสิทธิภาพที่ไม่สมบูรณ์)', '["100", "512", "1,000", "1,024", "2,048"]', '1,024', '["จำนวนดีเอ็นเอ = 1×2¹⁰ = 1,024 โมเลกุล"]', '["คำนวณ 2×10=20 (คูณธรรมดา) แทนที่จะยกกำลัง"]');
